mapper.update:
UPDATE baseline_task_host
SET status = #{status},
    result_summary = #{resultSummary}
WHERE id = #{id}

UPDATE baseline_task_host
SET status = #{status},
    result_summary = #{resultSummary}
WHERE id = #{id}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT id, tenant_id, task_name, execute_type, cron_expr, rule_scope, rule_snapshot_json, status,
       target_level, asset_type_filter, total_host_count, success_count, fail_count, creator,
       create_time, start_time, finish_time, protection_level_id
FROM baseline_task
WHERE id = #{id}
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE baseline_task_host
SET status = #{status},
    result_summary = #{resultSummary},
    scan_time = #{scanTime}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM baseline_task_host
WHERE task_id = #{taskId}
  AND status = #{status}

SELECT t.rule_scope
FROM baseline_task t
JOIN baseline_task_host th ON th.task_id = t.id
WHERE th.host_id = #{hostId}
  AND th.tenant_id = #{tenantId}
  AND t.tenant_id = #{tenantId}
ORDER BY th.id DESC
LIMIT 1
